SELECT 
FROM chatbi.bid_biz_purchase_intention

    AND province = #{province}
    AND city = #{city}
    AND industry = #{industry}
    AND info_type = #{infoType}
    AND tenderer LIKE CONCAT('%', #{tenderer}, '%')

        AND (
          title LIKE CONCAT('%', #{keyword}, '%')
          OR project_name LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
          OR keywords LIKE CONCAT('%', #{keyword}, '%')
        )

    AND bidding_budget >= #{minBudgetYuan}
    AND bidding_budget <= #{maxBudgetYuan}
    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT 
FROM chatbi.bid_biz_purchase_intention


        AND province IN

            #{p}






                    (title LIKE CONCAT('%', #{kw}, '%')
                     OR project_name LIKE CONCAT('%', #{kw}, '%')
                     OR product LIKE CONCAT('%', #{kw}, '%')
                     OR keywords LIKE CONCAT('%', #{kw}, '%')
                     OR tenderer LIKE CONCAT('%', #{kw}, '%'))







                title NOT LIKE CONCAT('%', #{kw}, '%')
                AND project_name NOT LIKE CONCAT('%', #{kw}, '%')
                AND product NOT LIKE CONCAT('%', #{kw}, '%')
                AND keywords NOT LIKE CONCAT('%', #{kw}, '%')
                AND tenderer NOT LIKE CONCAT('%', #{kw}, '%')



    AND bidding_budget >= #{minBudgetYuan}
    AND bidding_budget <= #{maxBudgetYuan}
    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}
